#include "recursion.h"
#include <stdbool.h>

static void foo_rec(bool *bits, int n, int i, FooStats *stats) {
    stats->calls++;

    if (i == n) {
        stats->leaves++;
        return;
    }

    /* Step 1: assign true at this position and recurse on i + 1. */
    /* Step 2: after that call returns, assign false and recurse again. */
}

FooStats foo(int n) {
    FooStats stats = {0, 0};
    bool bits[n > 0 ? n : 1];
    foo_rec(bits, n, 0, &stats);
    return stats;
}

